    display: flex; align-items: center; gap: 8px;
  }
  #disclaimer .icon { font-size: 14px; }
  /* Main Layout */
  #main {
    position: fixed; top: 82px; left: 0; right: 0; bottom: 0;
    display: flex; flex-direction: column;
  }
  /* Tabs */
  #tabs {
    display: flex; background: var(--panel); border-bottom: 1px solid var(--border);
    overflow-x: auto; flex-shrink: 0;
  }
  .tab-btn {
    flex: 1; min-width: 100px; padding: 10px 12px; border: none;
    background: transparent; color: var(--dim); font-size: 13px;
    cursor: pointer; border-bottom: 2px solid transparent;
    transition: all 0.2s; white-space: nowrap;
  }
  .tab-btn:hover { color: var(--text); background: rgba(255,255,255,0.03); }
  .tab-btn.active { color: var(--accent); border-bottom-color: var(--accent); }
  /* Content Area */
  #content {
    flex: 1; overflow: hidden; position: relative;
  }
  .tab-panel {
    display: none; width: 100%; height: 100%; position: absolute; top: 0; left: 0;
  }
  .tab-panel.active { display: flex; }
  /* Drawing Panel */
  #drawing-panel { flex-direction: row; }
  #drawing-canvas-wrap {
    flex: 1; position: relative; background: #fafafa;
    min-width: 0;
  }
  #drawing-canvas-wrap canvas {
    width: 100%; height: 100%; display: block;
  }
  #drawing-info {
    width: 280px; background: var(--panel); border-left: 1px solid var(--border);
    padding: 16px; overflow-y: auto; flex-shrink: 0;
  }
  #drawing-info h3 { font-size: 14px; margin-bottom: 8px; color: var(--accent); }
  #drawing-info p { font-size: 12px; line-height: 1.6; color: var(--dim); margin-bottom: 12px; }
  #drawing-info .note {
    background: #2a2000; border: 1px solid #5a4a1a; border-radius: var(--radius);
    padding: 8px; font-size: 11px; color: #f0c080; margin-bottom: 12px;
  }
  #drawing-nav {
    display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 16px;
  }
  #drawing-nav button {
    padding: 6px 12px; border: 1px solid var(--border); background: var(--bg);
    color: var(--text); border-radius: var(--radius); cursor: pointer; font-size: 12px;
  }
  #drawing-nav button.active { border-color: var(--accent); color: var(--accent); }
  /* 3D Panel */
  #model3d-wrap {
