  #process-panel { flex-direction: column; }
  #process-timeline {
    padding: 16px; background: var(--panel); border-bottom: 1px solid var(--border);
    display: flex; gap: 4px; overflow-x: auto; flex-shrink: 0;
  }
  .timeline-step {
    flex: 1; min-width: 120px; padding: 10px; border: 1px solid var(--border);
    background: var(--bg); border-radius: var(--radius); cursor: pointer;
    text-align: center; transition: all 0.2s;
