  .timeline-step .step-desc { font-size: 10px; color: var(--dim); }
  #process-3d-wrap {
    flex: 1; position: relative;
  }
  #process-3d-wrap canvas { width: 100%; height: 100%; display: block; }
  #process-info {
    position: absolute; bottom: 12px; left: 12px; right: 12px; z-index: 10;
    background: rgba(22,27,34,0.92); border: 1px solid var(--border);
    border-radius: var(--radius); padding: 14px;
    backdrop-filter: blur(8px);
  }
  #process-info h4 { font-size: 14px; color: var(--accent2); margin-bottom: 6px; }
  #process-info p { font-size: 12px; line-height: 1.6; color: var(--dim); }
  /* Responsive */
  @media (max-width: 768px) {
    #drawing-panel { flex-direction: column; }
    #drawing-info { width: 100%; max-height: 40vh; border-left: none; border-top: 1px solid var(--border); }
