<script>
(function() {
  'use strict';

  // ===== CONSTANTS =====
  const TOWER_HEIGHT = 555;
  const FLOORS = 123;
  const BASE_WIDTH = 42;
  const TOP_WIDTH = 14;
  const SEGMENTS = 5;
  const SEG_HEIGHT = TOWER_HEIGHT / SEGMENTS;

  // Segment widths (estimated from public photos)
  const SEG_WIDTHS = [BASE_WIDTH, 36, 30, 24, TOP_WIDTH];
  const SEG_NAMES = ['1~25층', '26~50층', '51~75층', '76~100층', '101~123층'];
  const SEG_COLORS = ['#4a90d9', '#5ba3e6', '#6cb6f3', '#7dc9ff', '#8edcff'];

  // ===== UTILITY =====
  function lerp(a, b, t) { return a + (b - a) * t; }
  function clamp(v, mn, mx) { return Math.max(mn, Math.min(mx, v)); }

  // ===== DRAWING SYSTEM =====
  const drawingCanvas = document.getElementById('drawing-canvas');
  const ctx = drawingCanvas.getContext('2d');
  let currentDrawing = 'site';

  const drawingInfo = {
    site: {
      title: '배치도 (Site Plan)',
      desc: `<p>서울 용산구 한강대로 424 일대에 위치한 롯데월드타워의 배치 개념도입니다.</p>
        <div class="note">⚠ 치수는 공개 자료를 참고한 추정치입니다. 실제 설계 치수와 다를 수 있습니다.</div>
        <p><b>주요 내용:</b></p>
        <p>• 타워 본체: 약 42m × 42m 기반<br>
           • 부대시설: 롯데월드, 쇼핑몰, 호텔<br>
           • 주변 도로: 한강대로, 용산로<br>
           • 방향: 북쪽(상단) 기준</p>
        <p><b>단위:</b> 도면 상 치수는 미터(m) 기준입니다.</p>`,
      label: '배치도',
      scale: '추정 스케일'
    },
    floor: {
      title: '기준층 평면도 (Typical Floor Plan)',
      desc: `<p>지상 30층대 기준층의 평면 개념도입니다. 타워는 4면 테이퍼 형태로 위로 갈수록 면적이 줄어듭니다.</p>
        <div class="note">⚠ 평면 형상과 치수는 공개 사진을 참고한 추정입니다. 실제 층별 평면과 다를 수 있습니다.</div>
        <p><b>주요 내용:</b></p>
        <p>• 외곽: 4면 테이퍼, 각 변 약 30m (30층대 추정)<br>
           • 코어: 중앙 승강기/계단 코어<br>
           • 외곽: 사무실/관람층<br>
           • 모서리: 곡면 처리</p>
        <p><b>단위:</b> 도면 상 치수는 미터(m) 기준입니다.</p>`,
      label: '기준층 평면도',
      scale: '1:500 (추정)'
    },
    elevation: {
      title: '입면도 (Elevation)',
      desc: `<p>롯데월드타워의 정면 입면 개념도입니다. 5개의 세그먼트로 나뉘며, 각 세그먼트마다 외곽이 좁아지는 테이퍼 형태입니다.</p>
        <div class="note">⚠ 세그먼트 높이와 너비는 공개 자료를 참고한 추정치입니다.</div>
        <p><b>주요 내용:</b></p>
        <p>• 총 높이: 555m (지상 123층)<br>
           • 기반 너비: 약 42m<br>
           • 상부 너비: 약 14m<br>
           • 5개 세그먼트로 분할<br>
           • 각 세그먼트 높이: 약 111m</p>
        <p><b>단위:</b> 도면 상 치수는 미터(m) 기준입니다.</p>`,
      label: '입면도',
      scale: '1:1000 (추정)'
    },
    section: {
      title: '단면도 (Section)',
      desc: `<p>타워의 중앙 단면 개념도입니다. 코어 구조와 층고 분포를 보여줍니다.</p>
        <div class="note">⚠ 구조 형상과 층고는 공개 자료를 참고한 추정입니다. 실제 구조 설계와 다를 수 있습니다.</div>
        <p><b>주요 내용:</b></p>
        <p>• 중앙 코어: 승강기/계단/설비<br>
           • 층고: 일반층 약 4m, 로비층 더 높음<br>
           • 5개 세그먼트별 테이퍼<br>
           • 옥상: 안테나/관제실</p>
        <p><b>단위:</b> 도면 상 치수는 미터(m) 기준입니다.</p>`,
      label: '단면도',
      scale: '1:1000 (추정)'
    }
  };

  function resizeDrawingCanvas() {
    const wrap = document.getElementById('drawing-canvas-wrap');
    const dpr = window.devicePixelRatio || 1;
    drawingCanvas.width = wrap.clientWidth * dpr;
    drawingCanvas.height = wrap.clientHeight * dpr;
    drawingCanvas.style.width = wrap.clientWidth + 'px';
    drawingCanvas.style.height = wrap.clientHeight + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawCurrent();
  }

  function drawCurrent() {
    const w = drawingCanvas.clientWidth;
    const h = drawingCanvas.clientHeight;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#fafafa';
    ctx.fillRect(0, 0, w, h);

    switch(currentDrawing) {
      case 'site': drawSitePlan(w, h); break;
      case 'floor': drawFloorPlan(w, h); break;
      case 'elevation': drawElevation(w, h); break;
      case 'section': drawSection(w, h); break;
    }
  }

  function drawGrid(ctx, w, h, spacing, color) {
    ctx.strokeStyle = color || '#e0e0e0';
    ctx.lineWidth = 0.5;
    for (let x = 0; x < w; x += spacing) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
    }
    for (let y = 0; y < h; y += spacing) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }
  }

  function drawDimLine(ctx, x1, y1, x2, y2, text, offset) {
    const dx = x2 - x1, dy = y2 - y1;
    const len = Math.sqrt(dx*dx + dy*dy);
    const nx = -dy/len * offset, ny = dx/len * offset;
    const px = dx/len * 10, py = dy/len * 10;

    ctx.strokeStyle = '#333';
    ctx.lineWidth = 0.8;
    ctx.beginPath();
    ctx.moveTo(x1 + nx, y1 + ny);
    ctx.lineTo(x2 + nx, y2 + ny);
    ctx.stroke();

    // ticks
    ctx.beginPath();
    ctx.moveTo(x1 + nx - px, y1 + ny - py);
    ctx.lineTo(x1 + nx + px, y1 + ny + py);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x2 + nx - px, y2 + ny - py);
    ctx.lineTo(x2 + nx + px, y2 + ny + py);
    ctx.stroke();

    // text
    ctx.fillStyle = '#333';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, (x1+x2)/2 + nx, (y1+y2)/2 + ny);
  }

  function drawSitePlan(w, h) {
    drawGrid(ctx, w, h, 40, '#e8e8e8');
    const cx = w/2, cy = h/2;
    const s = Math.min(w, h) / 100;

    // Roads
    ctx.fillStyle = '#d0d0d0';
    ctx.fillRect(0, cy - 25*s, w, 50*s); // horizontal road
    ctx.fillRect(cx - 20*s, 0, 40*s, h); // vertical road

    ctx.strokeStyle = '#999';
    ctx.lineWidth = 1;
    ctx.setLineDash([8, 4]);
    ctx.beginPath(); ctx.moveTo(0, cy); ctx.lineTo(w, cy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cx, 0); ctx
